    "id": "pt1-reading-m1-q1",
    "num": 1,
    "type": "Reading and Writing",
    "passage": "A study by Augusta D. Gaspar and Joana Carneiro Pinto found that a bank's corporate social responsibility (CSR) efforts, including environmental and social campaigns, improve its corporate image. When CSR was mentioned in bank marketing strategies, favorability scores assigned by study participants tended to ______ the scores assigned by participants when CSR wasn't mentioned.",
    "question": "Which choice completes the text with the most logical and precise word or phrase?",
    "options": [
      "identify",
      "disturb",
      "replace",
      "exceed"
    ],
    "answer": 3,
    "difficulty": "Medium",
    "explanation": `Words in Context

Answer: D \u2014 exceed

Core Logic: The study shows CSR improves corporate image \u2014 so favorability scores when CSR is mentioned would logically be higher than when CSR isn't mentioned, meaning they go beyond (exceed) the baseline scores.

\u2705 Why D is Correct

Choice D (exceed) is correct. The passage states that CSR efforts "improve" corporate image, which means scores should be higher when CSR is mentioned. "Exceed" (to go beyond or surpass) is the only word that captures this upward comparison. The sentence structure "tended to ______ the scores assigned by participants when CSR wasn't mentioned" calls for a comparative verb showing the CSR-mentioned scores are greater.

\u274C Why the Others Are Wrong

A (identify): "Identify the scores" makes no logical sense \u2014 favorability numbers don't identify other numbers.

B (disturb): "Disturb the scores" implies disruption or interference, not a comparison of magnitude.

C (replace): "Replace the scores" implies substitution rather than surpassing them, and contradicts the idea of comparison.`
