    "type": "Reading and Writing",
    "passage": "Science fiction has long served as a ______ real-world technological advancements. Indeed, from Jules Verne's 1865 novel <i>From the Earth to the Moon</i> inspiring developments in aerospace engineering to the television show <i>Star Trek</i> sparking the design of the ancestor of today's smartphones, these narratives have spurred many actual innovations.",
    "question": "Which choice completes the text with the most logical and precise word or phrase?",
    "options": [
      "diversion from",
      "catalyst of",
      "constraint to",
      "sponsor of"
    ],
    "answer": 1,
    "difficulty": "Medium",
    "explanation": `Words in Context

Answer: B \u2014 catalyst of

Core Logic: The passage says science fiction has "spurred many actual innovations" \u2014 something that triggers or drives change is a catalyst, not a diversion, constraint, or sponsor.

\u2705 Why B is Correct

Choice B (catalyst of) is correct. A catalyst is something that causes or accelerates a process. The passage proves this: Jules Verne's novel inspired aerospace engineering, and Star Trek sparked smartphone design. Science fiction initiated and accelerated these technological developments \u2014 the definition of a catalyst.

\u274C Why the Others Are Wrong

A (diversion from): "Diversion" implies science fiction leads people away from real-world tech \u2014 the opposite of what the passage says.

C (constraint to): A constraint limits development. The passage describes science fiction as an enabler, not a limitation.

D (sponsor of): A sponsor provides financial support \u2014 the passage never discusses money, only inspiration.`
