    "id": "pt1-reading-m1-q5",
    "num": 5,
    "type": "Reading and Writing",
    "passage": "Any effort to raise the toll that drivers must pay to use the Lewis and Clark Bridge, which spans the Ohio River to connect Indiana and Kentucky, should explain why a higher toll is necessary; no amount of justification, however, is likely to persuade some drivers who believe the current toll is ______.",
    "question": "Which choice completes the text with the most logical and precise word or phrase?",
    "options": [
      "exorbitant",
      "contentious",
      "equivocal",
      "warranted"
    ],
    "answer": 0,
    "difficulty": "Medium",
    "explanation": `Words in Context

Answer: A \u2014 exorbitant

Core Logic: Drivers who believe the toll is "_____" would resist a higher toll \u2014 they believe the current toll is already too high, meaning exorbitant (excessively high).

\u2705 Why A is Correct

Choice A (exorbitant) is correct. The passage sets up a contrast: efforts to raise the toll require explanation, but "no amount of justification" will persuade drivers who believe the current toll is already _____. For drivers to resist higher tolls regardless of justification, they must already see the current toll as unreasonably high \u2014 precisely what "exorbitant" means.

\u274C Why the Others Are Wrong

B (contentious): Contentious means controversial or disputed \u2014 but the passage is describing what the drivers personally believe about the toll's price level, not about whether the toll is debatable.

C (equivocal): Equivocal means ambiguous or unclear \u2014 a toll is a fixed number, not an ambiguous one.

D (warranted): If drivers believed the toll was warranted (justified), they would accept a higher toll, not resist it. This contradicts the logic.`
