    "num": 13,
    "type": "Reading and Writing",
    "passage": "The Raramuri language of northern Mexico has 20 vowel and consonant sounds. In contrast, the Taa language of southern Africa has over 100. Why would languages differ in this way? One researcher has claimed that when modern humans arose in Africa, they spoke a single language, but as humans gradually spread throughout Africa and then around the globe, that language developed into new languages. Those developed into still more languages as small bands of humans spread even farther, with each new language retaining fewer sounds from humanity's original language.",
    "question": "Which finding, if true, would most directly weaken the researcher's claim?",
    "options": [
      "A wider range of sounds is found across the languages of Africa as a whole than across the languages of South America as a whole.",
      "Languages that emerged in Europe and Western Asia tend to have more sounds than languages that emerged in Africa do.",
      "Languages that emerged in Central America tend to have fewer sounds than languages that emerged in Western Europe do, and Central America is farther away from Africa than Western Europe is.",
      "The number of sounds is fairly consistent across the various languages that emerged in the last parts of Africa to be settled by humans."
    ],
    "answer": 1,
    "difficulty": "Medium",
    "explanation": `Claims & Evidence (Weaken)

Answer: B

Core Logic: The researcher claims that the farther humans migrated from Africa, the fewer sounds their languages retained \u2014 so Africa-origin languages should have the most sounds, and non-Africa languages should have fewer proportional to distance. Any finding that breaks this gradient weakens the claim.

\u2705 Why B is Correct

Choice B is correct: "Languages that emerged in Europe and Western Asia tend to have more sounds than languages that emerged in Africa do." The researcher's claim predicts Africa has the most sounds (as the origin point), with sounds diminishing with distance. If European and Western Asian languages \u2014 which emerged farther from Africa \u2014 actually have more sounds than African languages, this directly contradicts the hypothesis that distance from Africa correlates with fewer sounds.

\u274C Why the Others Are Wrong

A: Africa having a wider range of sounds overall is consistent with the researcher's claim that Africa is the origin of maximum phonological diversity.

C: Central America having fewer sounds than Western Europe is actually consistent with the researcher's model \u2014 Central America is farther from Africa than Western Europe is.

D: Consistent variation among the last-settled African regions aligns with the idea of gradual sound reduction as populations spread \u2014 this supports rather than weakens.`
