    "passage": "Text 1\n\nSidebells wintergreen (<i>Orthilia secunda</i>) plants are native to Alaska, where harsh conditions have historically impeded potential invasive species. As the boreal climate has warmed in recent decades, however, Siberian peashrub (<i>Caragana arborescens</i>) plants have established themselves in Alaska. Previous research conducted in non-boreal ecosystems has documented warming-induced increases in summer temperatures benefiting invasive species more than native species.\n\nText 2\n\nAt a site near Fairbanks, Alaska, Christa Mulder and Katie Spellman tracked <i>O. secunda</i> and <i>C. arborescens</i>, along with other native and invasive species, over several years. They observed that although average summer temperatures were substantially higher in some years of the study than in others, neither <i>O. secunda</i> nor <i>C. arborescens</i> showed any significant variation in summer growth patterns from year to year.",
