    "num": 8,
    "type": "Reading and Writing",
    "passage": "Optimal foraging theory (OFT) holds that animals\u2019 foraging behaviors reflect cost-benefit trade-offs that vary by species and with dynamic ecological circumstances. One such circumstance is lunar intensity, which Mary V. Price and colleagues found to be negatively associated with foraging by white-throated woodrats but Simon Kenneth Bearder and colleagues found to be positively associated with foraging by Mohol bushbabies. This discrepancy is explicable in terms of OFT: the bushbabies\u2019 greater reliance on vision means that higher lunar intensity benefits them more than it benefits the woodrats.",
    "question": "Information in the text best supports which statement about Mohol bushbabies?",
    "options": [
      "lf increased lunar intensity imposed the same costs on the bushbabies that it imposes on white-throated woodrats, there would be no association between lunar intensity and the bushbabies\u2019 foraging.",
      "If the advantages that the bushbabies gain from increased lunar intensity explain the change in their foraging behavior, those advantages are likely shared by some other species that are not heavily reliant on vision.",
      "If increased lunar intensity creates any disadvantages for the bushbabies, those disadvantages are more than compensated for by the advantages that the bushbabies gain.",
      "If the bushbabies\u2019 foraging behavior under increased lunar intensity actually reflects a cost-benefit trade-off, their behavior should be more similar to that of white-throated woodrats than it is."
    ],
    "answer": 2,
    "difficulty": "Hard",
    "explanation": `Command of Evidence \xB7 Hard

Answer: C

Core Logic: The passage explains via OFT that bushbabies benefit from higher lunar intensity because of their reliance on vision. If increased moonlight benefits them more than it costs them, those advantages outweigh any disadvantages \u2014 which is what OFT's cost-benefit framework predicts.

\u2705 Why C is Correct

Choice C is correct: "If increased lunar intensity creates any disadvantages for the bushbabies, those disadvantages are more than compensated for by the advantages that the bushbabies gain." OFT predicts that animals' behaviors reflect net cost-benefit trade-offs. Bushbabies increase foraging when lunar intensity rises because the visual benefits (finding food more easily) outweigh any costs (e.g., predator visibility). This is consistent with OFT's framework.

\u274C Why the Others Are Wrong

A: If moonlight imposed the same costs, there would still be net benefits \u2014 the association wouldn't disappear; it would just be different. This doesn't follow from OFT.

B: OFT predicts species-specific responses based on their unique traits (like vision reliance). Non-visual species wouldn't share the same advantage from moonlight.

D: The passage says bushbabies and woodrats already show opposite responses \u2014 their behavior is clearly NOT more similar to woodrats, contradicting D.`
