    "passage": "In Puerto Rico, it\u2019s not unusual for a city or town to be known by a nickname that corresponds to one of its notable features, like landscape, climate, famous residents, or chief export. For example, the Puerto Rican municipality of Manati is well known for its history as a cultural center in the early 20th ______ this distinction has earned it the fitting nickname of \u201Cthe Athens of Puerto Rico.\u201D",
