    "difficulty": "Hard",
    "explanation": 'Boundaries (Punctuation) \xB7 Hard\n\nAnswer: D \u2014 century;\n\nCore Logic: "history as a cultural center in the early 20th century" is a complete noun phrase ending the first clause. What follows ("this distinction has earned it...") is an independent clause. A semicolon correctly joins two related independent clauses.\n\n\u2705 Why D is Correct\n\nChoice D (century;) is correct. The sentence structure is: "Manat\xED is well known for its history as a cultural center in the early 20th century; [+] this distinction has earned it the fitting nickname..." Two independent clauses are joined by a semicolon, which is the correct punctuation when no coordinating conjunction is used between two closely related complete sentences.\n\n\u274C Why the Others Are Wrong\n\nA (century and): "Century and this distinction has earned..." creates an awkward construction \u2014 "and" would need to connect parallel elements, but the two clauses are not parallel in this way without a comma before "and."\n\nB (century): No punctuation creates a run-on sentence \u2014 two independent clauses cannot be fused without punctuation or a conjunction.\n\nC (century,): A comma alone between two independent clauses creates a comma splice.'
