    "id": "pt1-reading-m2-q19",
    "num": 19,
    "type": "Reading and Writing",
    "passage": "Geologist and scholar John Bostock joined with 55 other prominent British writers in 1837 to petition the US Congress for greater copyright protections. This cadre of renowned ______ that American publishers\u2019 appropriation of their work caused, in the words of the petition, \u201Cdeep and extensive injuries...on their reputation and property,\u201D helped sow the seeds for the International Copyright Act of 1891.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "authors asserted",
      "authors were asserting",
      "authors, had asserted",
      "authors, asserting"
    ],
    "answer": 3,
    "difficulty": "Hard",
    "explanation": `Form, Structure & Sense (Grammar) \xB7 Hard

Answer: D \u2014 authors, asserting

Core Logic: The blank modifies "cadre of renowned ___" \u2014 "authors" names them, and then a participial phrase ("asserting that...") describes their action. A participial phrase in apposition to the noun correctly captures the idea without creating a run-on.

\u2705 Why D is Correct

Choice D (authors, asserting) is correct. The sentence: "This cadre of renowned authors, asserting that American publishers' appropriation of their work caused... injuries, helped sow the seeds for the International Copyright Act." "Authors" names the group; "asserting..." is a participial phrase (offset by a comma) describing the action the authors took \u2014 asserting a claim. This creates one unified sentence with the correct structure: subject (cadre) + participial modifier + main verb (helped sow).

\u274C Why the Others Are Wrong

A (authors asserted): Creates two independent clauses ("cadre...asserted that..." and "helped sow the seeds") fused without proper conjunction or punctuation \u2014 a run-on.

B (authors were asserting): Same problem \u2014 "cadre were asserting" and "helped sow" are two independent clauses improperly fused.

C (authors, had asserted): "Authors, had asserted" is not grammatically standard \u2014 the comma interrupts the subject-verb unit improperly.`
