    "explanation": "Algebra / Linear Equations\n\nAnswer: D \u2014 670\n\nCore Mathematical Concept: Recognizing that 90x + 40 is exactly 10 times (9x + 4), so the answer scales directly without solving for x.\n\n\u{1F4D0} Step-by-Step Proof\n\nGiven:  9x + 4 = 67\n\nNotice: 90x + 40 = 10(9x + 4)\n\nTherefore: 10 \xD7 67 = 670\n\nAnswer: D \u2014 670 \u2713\n\n\u{1F5A9} Desmos Method\n\nType 9x + 4 = 67 \u2192 find x = 7 \u2192 compute 90(7) + 40 = 670.\n\n\u274C Why Others Are Wrong\n\nA (7): This is the value of x, not 90x + 40.\n\nB (70): Multiplies 67 by ~1, not by 10. Confuses the scale factor.\n\nC (130): Adds 63 instead of multiplying \u2014 misreads the relationship between the expressions."
