    "answer": 2,
    "difficulty": "Medium",
    "explanation": "Algebra / Linear Models (Word Problem)\n\nAnswer: C \u2014 70\n\nCore Mathematical Concept: Linear decay model \u2014 subtract 0.9 pounds per day from initial weight 293; set equal to 230 and solve for days.\n\n\u{1F4D0} Step-by-Step Proof\n\nModel: Weight = 293 \u2212 0.9d\n\nSet equal to 230: 293 \u2212 0.9d = 230\n\n\u22120.9d = 230 \u2212 293 = \u221263\n\nd = \u221263 / \u22120.9 = 70\n\nAnswer: C \u2014 70 days \u2713\n\n\u{1F5A9} Desmos Method\n\nGraph y = 293 - 0.9x and y = 230. Find intersection x-coordinate = 70.\n\nA (57): Uses 0.9 incorrectly \u2014 perhaps divides 51 by 0.9 rather than 63.\n\nB (63): This is the raw weight difference (293 \u2212 230 = 63), but doesn't divide by the rate.\n\nD (207): Adds instead of subtracts, or divides the whole starting weight by 0.9."
