    "explanation": "Advanced Math / Quadratic Equations \u2014 Number of Solutions\n\nAnswer: C \u2014 Exactly two\n\nCore Mathematical Concept: Difference of squares \u2014 x\xB2 \u2212 (9/4)\xB2 = 0 factors into (x \u2212 9/4)(x + 9/4) = 0, yielding two distinct real solutions.\n\n\u{1F4D0} Step-by-Step Proof\n\nx\xB2 \u2212 81/16 = 0\n\nx\xB2 = 81/16\n\nx = \xB1\u221A(81/16) = \xB19/4\n\nTwo distinct real solutions: x = 9/4 and x = \u22129/4\n\nAnswer: C \u2014 Exactly two \u2713\n\n\u{1F5A9} Desmos Method\n\nGraph y = x^2 - 81/16. Count x-intercepts \u2192 exactly 2 (symmetric about y-axis).\n\nA (Zero): Incorrectly concludes no real solution \u2014 but 81/16 is positive, so the square root exists.\n\nB (Exactly one): Would require a perfect square equation like (x \u2212 k)\xB2 = 0 \u2014 this is a difference of squares, not a perfect square.\n\nD (Infinitely many): Only true for identities; this is a specific equation with a finite solution set."
