    "difficulty": "Medium",
    "explanation": "Algebra / Slopes of Perpendicular Lines\n\nAnswer: D \u2014 2/9\n\nCore Mathematical Concept: Perpendicular lines have slopes that are negative reciprocals. Find slope of h, then negate and flip.\n\n\u{1F4D0} Step-by-Step Proof\n\nLine h: (1/2)x + (1/9)y \u2212 54 = 0\n\nSolve for y: (1/9)y = \u2212(1/2)x + 54\n\ny = \u2212(9/2)x + 486\n\nSlope of h: m_h = \u22129/2\n\nPerpendicular slope: m_j = \u22121/m_h = \u22121/(\u22129/2) = 2/9\n\nAnswer: D \u2014 slope of j = 2/9 \u2713\n\nA (\u22129/2): This is the slope of h, not of the perpendicular line j.\n\nB (\u22122/9): Flips the fraction but keeps the wrong sign \u2014 perpendicular requires flipping AND negating.\n\nC (9/2): Negates but doesn't flip \u2014 gives the negative of h's slope, not its perpendicular."
