    "difficulty": "Hard",
    "explanation": "Advanced Math / Quadratic \u2014 Finding When Function = 0\n\nAnswer: 1.1\n\nCore Mathematical Concept: Use h(0) = 19.36 to find b, then set h(t) = 0 (ground level) and solve for t.\n\n\u{1F4D0} Step-by-Step Proof\n\nh(t) = \u221216t\xB2 + b\n\nh(0) = 19.36:  \u221216(0)\xB2 + b = 19.36  \u2192  b = 19.36\n\nSet h(t) = 0 (object hits ground):\n\n\u221216t\xB2 + 19.36 = 0\n\n16t\xB2 = 19.36\n\nt\xB2 = 19.36/16 = 1.21\n\nt = \u221A1.21 = 1.1\n\nt = 1.1 seconds \u2713\n\n\u{1F5A9} Desmos Method\n\nGraph y = -16x^2 + 19.36. Find positive x-intercept \u2192 x = 1.1.\n\nCommon error: Taking \u221A(19.36/16) = \u221A19.36/4 = 4.4/4 = 1.1 correctly, but some students get 19.36/4 = 4.84 (forgetting to square root at the end)."
