    "difficulty": "Hard",
    "explanation": `Advanced Math / Factoring \u2014 Common Factor Extraction

Answer: D \u2014 y + 5x \u2212 15

Core Mathematical Concept: Factor out the GCF from both terms, then recognize a difference of squares pattern in the remaining factor.

\u{1F4D0} Step-by-Step Proof

y\xB2(x\u22123) \u2212 25(x\u22123)\xB3

Factor out GCF = (x\u22123):

= (x\u22123)[y\xB2 \u2212 25(x\u22123)\xB2]

Recognize: y\xB2 \u2212 25(x\u22123)\xB2 = [y \u2212 5(x\u22123)][y + 5(x\u22123)]

  (difference of squares: a\xB2\u2212b\xB2 = (a\u2212b)(a+b))

Full factored form: (x\u22123)[y \u2212 5(x\u22123)][y + 5(x\u22123)]

Expand [y + 5(x\u22123)] = y + 5x \u2212 15

Factor: y + 5x \u2212 15 \u2192 Answer: D \u2713

A y(x\u22123): Partially factors only y from y\xB2 \u2014 incomplete; doesn't account for the full structure.

B (x\u22125)(x\u22123): Treats it as a quadratic in x \u2014 wrong variable structure; y is the "variable" in the difference of squares.

C (y+x\u22123): Drops the coefficient 5 from the factored term 5(x\u22123).`
