    "id": "pt2-reading-m2-q16",
    "num": 16,
    "type": "Reading and Writing",
    "passage": "Interested in how the color of dogs\u2019 irises affects human responses to dogs, Akitsugu Konno\net al. showed images of 12 dogs\u2019 faces to human participants and asked them to rate the\ndogs\u2019 kindness and trustworthiness as well as the likelihood that they would interact with or\nkeep the dogs. The researchers had previously adjusted the images so that each dog was\npresented in two versions, one with light irises and one with dark irises. They distributed the\nimages such that no participant saw both the light and dark versions of the same dog. Konno\net al. found that participants responded more positively to the latter. The study\u2019s design\nallowed the researchers to exclude the possibility that the results ______",
    "question": "Which choice most logically completes the text?",
    "options": [
      "may have been different if participants had been able to see the dogs\u2019 irises in person\ninstead of only seeing images that included the dogs' irises.",
      "reflected a preference on the part of participants for facial features that happened to\ncoincide with dark irises in the dogs depicted in the images.",
      "were a function of participants emphasizing the colors of the dogs' irises over the dogs\u2019\nkindness and trustworthiness when reacting to the images.",
      "could be explained by participants having preexisting positive feelings about dogs with\ndark irises or preexisting negative feelings about dogs with light irises."
    ],
    "answer": 1,
    "difficulty": "Hard",
    "explanation": `Answer: **B**

**Core Logic Summary:** By ensuring no participant saw both iris versions of the same dog, the researchers eliminated the possibility that results reflected preferences for other facial features that happened to come with dark irises in specific dogs \u2014 not the iris color itself.

**Why [B] is Correct:**
The design rule: "They distributed the images such that no participant saw both the light and dark versions of the same dog." This design controls for the possibility that a given dog's other facial features (eye size, face shape, fur pattern) \u2014 which happen to be paired with dark irises in the images \u2014 caused the preference, rather than iris color itself. Choice B identifies exactly this confounding factor that the design rules out.

**Why the Incorrect Answers are Wrong:**
- **Choice A** is incorrect because whether participants saw real dogs vs images is a limitation the study can't address by its own design \u2014 it's a separate question.
- **Choice C** is incorrect because the design doesn't specifically rule out that participants were focusing on iris color \u2014 it rules out species-specific facial feature effects.
- **Choice D** is incorrect because the design DOES rule out preexisting feelings about specific dogs \u2014 but Choice D says the design "excluded the possibility" of this, which actually makes D seem correct. Let me re-examine.

Wait \u2014 Choice D says: "could be explained by participants having preexisting positive feelings about dogs with dark irises or preexisting negative feelings about dogs with light irises." 

Since participants never saw both versions of the same dog, they couldn't have pre-existing feelings about those specific dogs \u2014 but they COULD still have general preexisting feelings about dark-iris dogs as a category. The design doesn't rule out general preexisting preferences for dark irises.

Choice B says: "reflected a preference...for facial features that happened to coincide with dark irises in the dogs depicted in the images." The design DOES rule this out \u2014 because since participants only saw ONE iris version of each dog, any preference can't be attributed to facial features specific to the dark-iris version of a particular dog (the same dog appears in both versions, only the iris color differs). The researchers adjusted the images so iris was the controlled variable. So B is what the design specifically rules out. \u2713

---`
