    "difficulty": "Medium",
    "explanation": "Answer: D (6n + 4 = 100)\nCore Mathematical Concept: Linear equations / Modeling (Heart of Algebra)\nStep-by-Step Proof:\nChoice D is correct. Let nn\nn = number of 9-inch parts.\nPartCount9-inchnn\nn8-inch5n5n\n5n3-inch44\n4\nTotal: 5n+n+4=100\u21D26n+4=1005n + n + 4 = 100 \\Rightarrow \\mathbf{6n + 4 = 100}\n5n+n+4=100\u21D26n+4=100.\nWhy the Incorrect Answers are Wrong:\n\n**A (8(5n)+9n+3(4)=1008(5n)+9n+3(4)=100\n8(5n)+9n+3(4)=100):** This sets up a total *value* (inches) equation, not a parts-count equation. The problem asks for the count.\nB (8n+9n+3n=1008n+9n+3n=100\n8n+9n+3n=100): Assigns the wrong coefficient \u2014 3-inch parts number 4 (fixed), not 3n3n\n3n.\nC (5n+4=1005n+4=100\n5n+4=100): Leaves out the nn\nn 9-inch parts themselves."
