    "explanation": 'Answer: D (N = 200(2.20)^{\\frac{t}{4}})\nCore Mathematical Concept: Exponential models (Advanced Math)\nStep-by-Step Proof:\nChoice D is correct.\n"120% more" means each 4-year period multiplies the population by 1+1.20=2.201 + 1.20 = 2.20\n1+1.20=2.20.\n\nAt t=0t = 0\nt=0: N=200N = 200\nN=200 \u2713\nAt t=4t = 4\nt=4 (one 4-year period): N=200\xD72.204/4=200\xD72.20=440N = 200 \\times 2.20^{\\frac{4}{4}} = 200 \\times 2.20 = 440\nN=200\xD72.204/4=200\xD72.20=440 \u2713 (120% more than 200 = 440)\nAt t=8t = 8\nt=8: N=200\xD72.208/4=200\xD72.202=968N = 200 \\times 2.20^{\\frac{8}{4}} = 200 \\times 2.20^2 = 968\nN=200\xD72.208/4=200\xD72.202=968 \u2713\n\nThe exponent is t4\\dfrac{t}{4}\n4t\u200B because one period passes every 4 years.\nN=200(2.20)t/4\\boxed{N = 200(2.20)^{\\frac{t}{4}}}N=200(2.20)t/4\u200B\nWhy the Incorrect Answers are Wrong:\n\nA (200(2.20)4t200(2.20)^{4t}\n200(2.20)4t): Exponent grows 16\xD7 too fast \u2014 after just t=1t=1\nt=1 year the population would be ~4,686.\nB (200(1.20)4t200(1.20)^{4t}\n200(1.20)4t): Uses 1.20 (which would be "20% more"), and the 4t4t\n4t exponent grows too fast.\nC (200(1.20)t/4200(1.20)^{\\frac{t}{4}}\n200(1.20)t/4): Uses 1.20 which represents only a 20% increase, not 120%.'
