    "question": "$$r(x) = 13(x - 2)$$\n$$s(x) = x^3 + nx^2 + 2nx + 8$$\n\nFor the given functions $r$ and $s$, $n$ is a constant. If $r(x) \\cdot s(x) = 13(x^4 - 16)$, what is the\nvalue of $n$?",
    "options": [],
    "answer": "2",
    "difficulty": "Hard",
    "explanation": "Answer: 2\nCore Mathematical Concept: Polynomial multiplication / Factoring (Advanced Math)\nStep-by-Step Proof:Answer is 2\\mathbf{2}\n2.\nr(x)\u22C5s(x)=13(x4\u221216)r(x) \\cdot s(x) = 13(x^4 - 16)r(x)\u22C5s(x)=13(x4\u221216)\n13(x\u22122)\u22C5s(x)=13(x4\u221216)13(x - 2) \\cdot s(x) = 13(x^4 - 16)13(x\u22122)\u22C5s(x)=13(x4\u221216)\n(x\u22122)\u22C5s(x)=x4\u221216(x - 2) \\cdot s(x) = x^4 - 16(x\u22122)\u22C5s(x)=x4\u221216\nFactor the right side:\nx4\u221216=(x2\u22124)(x2+4)=(x\u22122)(x+2)(x2+4)x^4 - 16 = (x^2 - 4)(x^2 + 4) = (x - 2)(x + 2)(x^2 + 4)x4\u221216=(x2\u22124)(x2+4)=(x\u22122)(x+2)(x2+4)\nTherefore:\ns(x)=(x+2)(x2+4)=x3+2x2+4x+8s(x) = (x + 2)(x^2 + 4) = x^3 + 2x^2 + 4x + 8s(x)=(x+2)(x2+4)=x3+2x2+4x+8\nCompare with s(x)=x3+nx2+2nx+8s(x) = x^3 + nx^2 + 2nx + 8\ns(x)=x3+nx2+2nx+8:\nn=2and2n=4\u21D2n=2\xA0\u2713n = 2 \\quad \\text{and} \\quad 2n = 4 \\Rightarrow n = 2 \\text{ \u2713}n=2and2n=4\u21D2n=2\xA0\u2713"
