    "explanation": "Answer: D (440)\nCore Mathematical Concept: Similar figures / Proportional scaling (Geometry)\nStep-by-Step Proof:\nChoice D is correct.\nFor Rectangle A, let sides be LL\nL and WW\nW:\n\nLW=660and2(L+W)=220\u21D2L+W=110LW = 660 \\quad \\text{and} \\quad 2(L+W) = 220 \\Rightarrow L + W = 110LW=660and2(L+W)=220\u21D2L+W=110\nScale factor between similar rectangles:\n\nk2=AreaBAreaA=2640660=4\u21D2k=2k^2 = \\frac{\\text{Area}_B}{\\text{Area}_A} = \\frac{2640}{660} = 4 \\Rightarrow k = 2k2=AreaA\u200BAreaB\u200B\u200B=6602640\u200B=4\u21D2k=2\nPerimeters scale by kk\nk:\n\nn=220\xD72=440n = 220 \\times 2 = \\mathbf{440}n=220\xD72=440\nAlternative / Desmos Method:Solve L+W=110L + W = 110\nL+W=110 and LW=660LW = 660\nLW=660: L=55\xB13025\u2212660=55\xB12365L = 55 \\pm \\sqrt{3025-660} = 55 \\pm \\sqrt{2365}\nL=55\xB13025\u2212660\u200B=55\xB12365\u200B. Rectangle B sides are twice as long, so perimeter = 4(L+W)=4\xD7110=4404(L+W) = 4 \\times 110 = 440\n4(L+W)=4\xD7110=440.\nWhy the Incorrect Answers are Wrong:\n\nA (2,200): Multiplies perimeter by k2=4k^2 = 4\nk2=4 instead of k=2k = 2\nk=2.\nB (1,760): No clear mathematical derivation.\nC (880): Multiplies by k2/2k^2/2\nk2/2 \u2014 a mixed error."
